namespace ghidra.app.plugin.core.processors;

using static org.junit.Assert;



using org.junit;

using ghidra.app.plugin.core.codebrowser;
using ghidra.app.plugin.core.navigation;
using ghidra.app.services;
using ghidra.framework.plugintool;
using ghidra.program.database;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.test;
using ghidra.test;

public class InstructionInfoTest : AbstractGhidraHeadedIntegrationTest {

	private static readonly string startAddressString = "1000000";
	private static readonly byte[] BYTES =
		new byte[] { (byte) 0xff, 0x15, 0x10, 0x32, 0x00, 0x01, (byte) 0xff, 0x75, 0x14 };
	private TestEnv env;
	private PluginTool tool;
	private ProgramBuilder builder;
	private Program program;
	private CodeBrowserPlugin cb;

	public InstructionInfoTest() : base()
    {
	}

	private Address addr(string address) {
		return program.getAddressFactory().getAddress(address);
	}

	/* @Before */
	public void setUp()
    {
		env = new TestEnv();
		tool = env.getTool();
		setupTool(tool);
		builder = new ProgramBuilder("test", ProgramBuilder._X86);
		builder.createMemory(".text", startAddressString, 0x1000);
		builder.setBytes(startAddressString, BYTES);
		builder.disassemble(startAddressString, BYTES.length);
		program = builder.getProgram();
		ProgramManager pm = tool.getService(typeof(ProgramManager));
		pm.openProgram(program);
		env.getPlugin(typeof(NextPrevAddressPlugin));
	}

	private void setupTool(PluginTool tool)
    {
		tool.addPlugin(typeof(CodeBrowserPlugin).getName());
		tool.addPlugin(typeof(NextPrevAddressPlugin).getName());
		tool.addPlugin(typeof(ShowInstructionInfoPlugin).getName());

		cb = getPlugin(tool, typeof(CodeBrowserPlugin));
	}

	/* @After */
	public void tearDown() {
		builder.dispose();
		env.dispose();
	}

	/* @Test */
	public void testRawInstructionDisplay() {
		env.showTool();
		ShowInstructionInfoPlugin p = getPlugin(tool, typeof(ShowInstructionInfoPlugin));
		JLabel label = p.getInstructionLabel();

		cb.goToField(addr("0x1000000"), "Address", 0, 0);
		assertEquals(" CALL dword ptr [0x01003210] ", label.getText());
		cb.goToField(addr("0x1000006"), "Address", 0, 0);
		assertEquals(" PUSH dword ptr [EBP + 0x14] ", label.getText());
	}

}
